import React, { useState, useEffect } from 'react';
import { Chart } from 'react-google-charts';
import axios from 'axios';
import './Visualization.css';

function Visualization() {
  const [columns, setColumns] = useState([]);
  const [selectedX, setSelectedX] = useState('age');
  const [selectedY, setSelectedY] = useState('bmi');
  const [chartData, setChartData] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // Load available columns
    axios.get('http://localhost:8000/data/columns')
      .then(res => {
        const numericColumns = res.data.columns.filter(col => 
          col !== 'diabetes' && 
          col !== 'gender' && 
          col !== 'smoking_history'
        );
        setColumns(numericColumns);
      });
  }, []);

  useEffect(() => {
    if (selectedX && selectedY) {
      setLoading(true);
      axios.get('http://localhost:8000/data/sample', {
        params: { 
          x: selectedX, 
          y: selectedY,
          limit: 100 
        }
      })
      .then(res => {
        const data = [
          [selectedX, selectedY],
          ...res.data.map(item => [item[selectedX], item[selectedY]])
        ];
        setChartData(data);
      })
      .finally(() => setLoading(false));
    }
  }, [selectedX, selectedY]);

  return (
    <div className="visualization">
      <h2>Data Visualization</h2>
      
      <div className="controls">
        <div>
          <label>X-Axis:</label>
          <select 
            value={selectedX} 
            onChange={e => setSelectedX(e.target.value)}
            disabled={loading}
          >
            {columns.map(col => (
              <option key={`x-${col}`} value={col}>{col}</option>
            ))}
          </select>
        </div>

        <div>
          <label>Y-Axis:</label>
          <select 
            value={selectedY} 
            onChange={e => setSelectedY(e.target.value)}
            disabled={loading}
          >
            {columns.map(col => (
              <option key={`y-${col}`} value={col}>{col}</option>
            ))}
          </select>
        </div>
      </div>

      {loading ? (
        <div className="loading">Loading chart...</div>
      ) : chartData.length > 1 ? (
        <Chart
          chartType="ScatterChart"
          width="100%"
          height="400px"
          data={chartData}
          options={{
            title: `${selectedY} vs ${selectedX}`,
            hAxis: { title: selectedX },
            vAxis: { title: selectedY },
            legend: 'none'
          }}
        />
      ) : (
        <div className="no-data">Select parameters to visualize</div>
      )}
    </div>
  );
}

export default Visualization;
